CREATE TABLE `tb_order_cancellations` (
  `ID` int unsigned NOT NULL AUTO_INCREMENT,
  `order_ID` int unsigned DEFAULT NULL,
  `buyer_order_ID` int unsigned DEFAULT NULL,
  `requested_by_user_ID` int unsigned DEFAULT NULL,
