CREATE DEFINER=`root`@`localhost` FUNCTION `fn_pais_aleatorio`(p_pais CHAR(2)) RETURNS char(2) CHARSET utf8mb4
    NO SQL
    DETERMINISTIC
BEGIN
    IF p_pais IS NOT NULL AND p_pais <> '*' THEN
        RETURN p_pais;
