DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_actualizar_stock_producto`(
    IN p_product_id INT UNSIGNED,
    IN p_nuevo_stock INT
)
BEGIN
    DECLARE v_existe INT;

    IF p_nuevo_stock < 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El valor de stock no puede ser negativo.';
    END IF;

    SELECT COUNT(*) INTO v_existe FROM `tb_products` WHERE `ID` = p_product_id;

    IF v_existe = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El producto especificado no existe.';
    END IF;

    START TRANSACTION;
    UPDATE `tb_products` 
    SET `current_stock` = p_nuevo_stock,
        `status` = IF(p_nuevo_stock = 0, b'0', `status`)
    WHERE `ID` = p_product_id;
    COMMIT;

    SELECT CONCAT('Stock actualizado para el producto ID ', p_product_id) AS resultado;
END ;;
DELIMITER ;
