/*!50003 DROP PROCEDURE IF EXISTS `sp_soft_delete_user` */;
/*!50003 SET @saved_cs_client      = @@character_set_client */ ;
/*!50003 SET @saved_cs_results     = @@character_set_results */ ;
/*!50003 SET @saved_col_connection = @@collation_connection */ ;
/*!50003 SET character_set_client  = utf8mb4 */ ;
/*!50003 SET character_set_results = utf8mb4 */ ;
/*!50003 SET collation_connection  = utf8mb4_0900_ai_ci */ ;
/*!50003 SET @saved_sql_mode       = @@sql_mode */ ;
/*!50003 SET sql_mode              = 'ONLY_FULL_GROUP_BY,STRICT_TRANS_TABLES,NO_ZERO_IN_DATE,NO_ZERO_DATE,ERROR_FOR_DIVISION_BY_ZERO,NO_ENGINE_SUBSTITUTION' */ ;
DELIMITER ;;
CREATE DEFINER=`root`@`localhost` PROCEDURE `sp_soft_delete_user`(
    IN p_user_id INT UNSIGNED
)
BEGIN
    DECLARE v_existe INT;

    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL SET MESSAGE_TEXT = 'Error al inhabilitar la cuenta del usuario.';
    END;

    SELECT COUNT(*) INTO v_existe FROM `tb_users` WHERE `ID` = p_user_id;

    IF v_existe = 0 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'El ID de usuario especificado no existe.';
    END IF;

    START TRANSACTION;
    UPDATE `tb_users` SET `status` = b'0' WHERE `ID` = p_user_id;
    UPDATE `tb_people` SET `status` = b'0' WHERE `user_ID` = p_user_id;
    COMMIT;

    SELECT CONCAT('El usuario con ID ', p_user_id, ' ha sido inhabilitado correctamente.') AS resultado;
END ;;
DELIMITER ;
